<script>
 import {archiveSession,archiveAvailability} from './archive-state.js';
 import {archiveMenuItems} from './archive-menus.js';
 import './archive.css';
 let {state: archiveUtilityState,profile,windowId,available=true,active=true,execute,registerView,listFiles,getFile}=$props();
 let root,scroller,error=$state('');
 let session=$derived(archiveSession(archiveUtilityState,windowId)),capability=$derived(archiveAvailability(profile)),busy=$derived(session?.status==='running');
 let bound=$derived([listFiles,getFile,execute,registerView].every(value=>typeof value==='function'));
 let files=$derived(bound?listFiles().filter(f=>!f.deleted&&f.parentId!==null&&!['desktop','documents','downloads','pictures','trash','icloud-drive','mail-cache'].includes(f.id)&&(session?.mode==='compress'||f.kind!=='folder')):null);
 async function send(command,payload={}){const result=await execute?.(command,{windowId},payload);error=result?.status==='rejected'?result.error?.message??'Archive command unavailable.':'';return result;}
 function preference(key,value){return send('archive.preferences',{values:{...archiveUtilityState.preferences,[key]:value}});}
 function drop(event){event.preventDefault();if(busy)return;let ids=[];const many=event.dataTransfer?.getData('application/x-jesteros-file-ids'),one=event.dataTransfer?.getData('application/x-jesteros-file-id');try{ids=many?JSON.parse(many):one?[one]:[];}catch{error='Invalid Files selection.';return;}if(!Array.isArray(ids)||!ids.length||ids.some(id=>typeof id!=='string')){error='Drag actual virtual Files, not host files.';return;}send('archive.select',{fileIds:ids,mode:session.mode});}
 $effect(()=>{const id=windowId;if(!root||typeof registerView!=='function')return;const originalRoot=root,originalState=archiveUtilityState,originalSession=session,originalScroller=scroller,mounted=()=>root===originalRoot&&originalRoot.isConnected&&archiveUtilityState===originalState&&archiveSession(archiveUtilityState,id)===originalSession&&available===true;const facade={available:mounted,focus(controlId,guard){if(guard?.()!==true||!mounted())return false;const control=Array.from(originalRoot.querySelectorAll('[data-control]')).find(node=>node.dataset.control===controlId);if(!control||control.disabled)return false;control.focus();return guard()===true&&mounted()&&document.activeElement===control;},scroll({top},guard){if(guard?.()!==true||!mounted()||!originalScroller||scroller!==originalScroller)return false;originalScroller.scrollTop=top;return guard()===true&&mounted()&&Math.abs(originalScroller.scrollTop-Math.min(top,Math.max(0,originalScroller.scrollHeight-originalScroller.clientHeight)))<1;}};const unregister=registerView(id,facade);return ()=>unregister?.();});
</script>
{#if session&&bound}
<section bind:this={root} class="archive-app" class:classic={/high-sierra|mojave/u.test(profile.id)} class:windows={profile.id.startsWith('windows11')} class:active aria-label={capability.label} ondragover={event=>event.preventDefault()} ondrop={drop}>
 <nav class="archive-menus" aria-label="Archive Utility menus">{#each archiveMenuItems(archiveUtilityState,windowId) as menu}<details><summary>{menu.label}</summary><div>{#each menu.items as item}<button disabled={!item.enabled} onclick={()=>send(item.command,item.payload)}>{item.label}</button>{/each}</div></details>{/each}</nav>
 <div class="archive-progress-panel"><div class="archive-icon" aria-hidden="true">▤<span>↓</span></div><div class="archive-progress-copy"><h2>{busy?(session.mode==='compress'?'Archiving…':'Expanding…'):session.status==='complete'?'Operation complete':session.status==='cancelled'?'Operation cancelled':session.status==='error'?'Unable to complete operation':'Archive Utility'}</h2><p>{session.fileIds.length?session.fileIds.map(id=>getFile(id)?.name??id).join(', '):'Choose a virtual file or folder to compress, or an archive to expand.'}</p><progress max="100" value={session.progress} aria-label="Archive progress"></progress><div class="archive-progress-footer"><span>{session.progress}%{busy?' · Local virtual Files only':''}</span><button data-control="cancel" disabled={!busy} onclick={()=>send('archive.cancel')}>Cancel</button></div></div></div>
 <div class="archive-controls"><label>Operation<select data-control="mode" value={session.mode} disabled={busy} onchange={event=>send('archive.configure',{mode:event.currentTarget.value})}><option value="compress">Create archive</option><option value="expand">Expand archive</option></select></label>{#if session.mode==='compress'}<label>Archive format<select data-control="format" value={session.format} disabled={busy} onchange={event=>send('archive.configure',{format:event.currentTarget.value})}><option value="zip">ZIP archive</option><option value="tar">USTAR archive</option><option value="gzip">Gzip — one file</option></select></label><label>Name<input data-control="name" value={session.outputName} disabled={busy} maxlength="230" placeholder="Automatic source name" onchange={event=>send('archive.configure',{outputName:event.currentTarget.value})}/></label>{/if}<label>Save {session.mode==='expand'?'expanded files':'archive'}<select data-control="destination" value={session.destination} disabled={busy} onchange={event=>send('archive.configure',{destination:event.currentTarget.value})}><option value="default">Use preferences</option><option value="same">Into the same folder</option><option value="documents">Documents</option><option value="desktop">Desktop</option><option value="downloads">Downloads</option></select></label></div>
 <div class="archive-actions"><button data-control="choose" disabled={busy} onclick={()=>send('archive.open',{mode:session.mode})}>{session.mode==='compress'?'Choose Files or Folder…':'Choose Archive…'}</button><button data-control="run" class="archive-default" disabled={busy||!session.fileIds.length} onclick={()=>send('archive.run')}>{session.mode==='compress'?'Create Archive':'Expand Archive'}</button></div>
 <details class="archive-file-list"><summary>Local virtual files ({files.length})</summary><div>{#each files as file}<label><input type="checkbox" disabled={busy} checked={session.fileIds.includes(file.id)} onchange={event=>send('archive.select',{mode:session.mode,fileIds:event.currentTarget.checked?(session.mode==='expand'?[file.id]:[...session.fileIds,file.id]):session.fileIds.filter(id=>id!==file.id)})}/><span>{file.name}</span></label>{/each}</div></details>
 <div bind:this={scroller} class="archive-results">{#if session.resultFileIds.length}<h3>Resulting Files</h3>{#each session.resultFileIds as id}<button onclick={()=>send('archive.reveal',{fileId:id})}>{getFile(id)?.name??id} <span>Show in {profile.id.startsWith('windows11')?'Files':'Finder'}</span></button>{/each}{/if}{#if session.log.length}<details><summary>Operation log</summary><ol>{#each session.log as row}<li>{row.message}</li>{/each}</ol></details>{/if}</div>
 {#if error||session.error}<p class="archive-error" role="alert">{error||session.error}</p>{/if}
 <footer><span>{capability.disclosure}</span><button data-control="preferences" disabled={busy} onclick={()=>send('archive.panel',{panel:'preferences'})}>{(/sonoma|golden-gate/u.test(profile.id))?'Settings…':'Preferences…'}</button></footer>
 {#if session.panel!=='none'}
 <div class="archive-sheet-shade"><section class="archive-sheet" role="dialog" aria-modal="true" aria-label={session.panel==='preferences'?'Archive Utility Preferences':'Archive Utility Help'}>
 {#if session.panel==='preferences'}
 <h2>Archive Utility {(/sonoma|golden-gate/u.test(profile.id))?'Settings':'Preferences'}</h2>
 <div class="archive-pref-group">
  <label>Save expanded files<select data-control="expand-destination" value={archiveUtilityState.preferences.expandDestination} onchange={event=>preference('expandDestination',event.currentTarget.value)}><option value="same">into the same directory as the archive</option><option value="documents">into Documents</option><option value="desktop">onto Desktop</option><option value="downloads">into Downloads</option></select></label>
  <label>After expanding<select value={archiveUtilityState.preferences.afterExpand} onchange={event=>preference('afterExpand',event.currentTarget.value)}><option value="keep">leave archive alone</option><option value="trash">move archive to Trash</option><option value="delete">delete archive</option></select></label>
  <label class="archive-check"><input type="checkbox" checked={archiveUtilityState.preferences.revealExpanded} onchange={event=>preference('revealExpanded',event.currentTarget.checked)}/>Reveal expanded item(s) in {profile.id.startsWith('windows11')?'Files':'Finder'}</label>
  <label class="archive-check"><input type="checkbox" checked={archiveUtilityState.preferences.keepExpanding} onchange={event=>preference('keepExpanding',event.currentTarget.checked)}/>Keep expanding if possible</label>
 </div>
 <div class="archive-pref-group">
  <label>Save archive<select value={archiveUtilityState.preferences.compressDestination} onchange={event=>preference('compressDestination',event.currentTarget.value)}><option value="same">into the same directory as the files</option><option value="documents">into Documents</option><option value="desktop">onto Desktop</option><option value="downloads">into Downloads</option></select></label>
  <label>Use archive format<select value={archiveUtilityState.preferences.format} onchange={event=>preference('format',event.currentTarget.value)}><option value="zip">ZIP archive</option><option value="tar">USTAR archive</option><option value="gzip">Gzip — one file only</option></select></label>
  <label>After archiving<select value={archiveUtilityState.preferences.afterCompress} onchange={event=>preference('afterCompress',event.currentTarget.value)}><option value="keep">leave files alone</option><option value="trash">move files to Trash</option><option value="delete">delete files</option></select></label>
  <label class="archive-check"><input type="checkbox" checked={archiveUtilityState.preferences.revealArchive} onchange={event=>preference('revealArchive',event.currentTarget.checked)}/>Reveal archive in {profile.id.startsWith('windows11')?'Files':'Finder'}</label>
 </div>
 <label>Existing names<select value={archiveUtilityState.preferences.collision} onchange={event=>preference('collision',event.currentTarget.value)}><option value="rename">Keep both — append a number</option><option value="error">Stop with collision error</option></select></label>
 <p>All destinations and Trash actions affect virtual Files only. Unsupported formats and unsafe paths are rejected; sources are discarded only together with a successful result. Keep expanding unwraps a sole nested ZIP, TAR or Gzip member, up to four layers.</p>
 {:else}
 <h2>Archive Utility Help</h2><p>Use File → Create Archive or Expand Archive, or Finder’s Compress/Open integration. Drag actual virtual Files onto this window. ZIP supports files and folders with DEFLATE; TAR writes USTAR; Gzip compresses one file.</p><p>Operations are bounded to 128 entries, 720,000 container bytes and 1 MiB of expanded bytes. Encrypted ZIP, symlinks, TAR extensions and multi-member Gzip are not supported. Cancel stops processing before any Files publication.</p><p>Preferences select the destination, collision policy and whether to keep, trash or delete source items after success. Every result and source disposition is committed atomically.</p>{#if !profile.id.startsWith('windows11')}<p>System utility — no default Dock presence. Exact Mojave system-path verification is recorded separately in research evidence.</p>{/if}
 {/if}
 <div class="archive-sheet-buttons"><button data-control="done" onclick={()=>send('archive.panel',{panel:'none'})}>Done</button></div>
 </section></div>
 {/if}
</section>
{:else if session}
<section class="archive-app" aria-label={capability.label}><p class="archive-error" role="alert">Archive Utility is unavailable: Root must bind the actual shared Files inventory, original File getter, command executor and native view registrar. No archive controls or source facade are active.</p></section>
{/if}
